import zipfile, re
z=zipfile.ZipFile('/root/event_announcement_ready.hwpx')
found=False
for name in z.namelist():
    try:
        data=z.read(name).decode('utf-8','replace')
    except Exception:
        continue
    matches=re.findall(r'\{\{.*?\}\}', data) if '{{' in data else []
    if matches:
        print('REMAINING PLACEHOLDERS in', name, ':', matches)
        found=True
if not found:
    print('OK: No placeholders remain')
