import zipfile, json
with open('/root/event_data.json','r',encoding='utf-8') as f:
    data=json.load(f)
z=zipfile.ZipFile('/root/event_announcement_ready.hwpx')
all_text=''
for name in z.namelist():
    try:
        all_text += z.read(name).decode('utf-8','replace')
    except Exception:
        pass
for k,v in data.items():
    if str(v) in all_text:
        print(f'OK: {k} found')
    else:
        print(f'MISSING: {k} NOT found')
